const headers = $json.headers ?? {};
const supplied = headers['x-codenativex-intake-key'] ?? headers['X-CodeNativeX-Intake-Key'];
if (!supplied || supplied !== $env.N8N_WEBHOOK_SECRET) throw new Error('Unauthorized outreach webhook');
return $input.all();

const body = $json.body ?? $json;
const ids = Array.isArray(body.leadIds) ? body.leadIds : body.leadId ? [body.leadId] : [];
const mode = body.mode === 'send_approved' ? 'send_approved' : 'draft_only';
if (!ids.length) throw new Error('leadIds is required');
return ids.map(leadId => ({ json: { leadId, mode } }));

const original = $('Normalize Outreach Items').item.json;
if ($json.error) {
 const message=String($json.error.message ?? $json.error);
 const status=Number($json.error.statusCode ?? $json.error.httpCode ?? $json.statusCode ?? 0);
 if (original.mode === 'draft_only' && (status===409 || /\b409\b/.test(message)) && /audit|website|finding/i.test(message)) return [{json:{...original,needsAudit:true}}];
 throw new Error(message);
}
return [{json:{...$json,needsAudit:false}}];

const context = $('Get Safe Outreach Context').item.json;
const responseContent = Array.isArray($json.output)
  ? $json.output.flatMap(item => Array.isArray(item.content) ? item.content : []).find(item => item?.type === 'output_text')
  : undefined;
const raw = responseContent?.text ?? $json.message?.content ?? $json.choices?.[0]?.message?.content ?? $json.text ?? $json.output ?? '';
const cleaned = typeof raw === 'string'
  ? raw.replace(/^```json\s*/i, '').replace(/```$/,'').trim()
  : raw;
const draft = typeof cleaned === 'object' && cleaned !== null ? cleaned : JSON.parse(String(cleaned));
if (!draft.subject || !draft.body || !Array.isArray(draft.finding_codes)) throw new Error('AI did not return the required JSON shape');
draft.body = String(draft.body)
  .replace(/\n+(Best regards|Kind regards|Warm regards|Regards|Sincerely|Best),?\s*(?:\n.*)?$/i, '')
  .trim();
return [{ json: { leadId: context.leadId, subject: String(draft.subject).trim(), body: draft.body, findingCodes: draft.finding_codes } }];

const context = $('Get Safe Outreach Context').item.json;
const failed = Boolean($json.error || !($json.id ?? $json.messageId) || !$json.threadId);
return [{ json: { leadId: context.leadId, sendKey: context.sendKey, outcome: failed ? 'failed' : 'sent', gmailMessageId: failed ? undefined : ($json.id ?? $json.messageId), gmailThreadId: failed ? undefined : ($json.threadId), error: failed ? String($json.error.message ?? $json.error) : undefined } }];

const context = $('Get Safe Outreach Context').item.json;
const sendResult = $('Build Gmail Send Result').item.json;
const adminEmail = String($env.CODENATIVEX_ADMIN_NOTIFICATION_EMAIL ?? $env.CODENATIVEX_CONTACT_EMAIL ?? '').trim();
const dashboardBase = String($env.CODENATIVEX_ADMIN_DASHBOARD_URL ?? 'http://localhost:3000').replace(/\/$/, '');
const shouldNotify = sendResult.outcome === 'sent' && Boolean(sendResult.gmailMessageId) && Boolean(adminEmail);
const escapeHtml = (value) => String(value ?? '').replace(/[&<>\"']/g, character => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', "'": '&#39;' })[character]);
const companyName = context.companyName || 'Unknown company';
const reportFilename = context.reportFilename || 'No audit report';
const sentAt = new Date().toISOString();
const auditLabel = 'Prepared internally; not attached to the first email.';
const adminSubject = `Outreach sent: ${companyName}`;
const adminHtml = `<!doctype html><html><body style="margin:0;padding:24px;background:#070a11;font-family:Arial,sans-serif;color:#e9eef8"><table role="presentation" width="100%" cellspacing="0" cellpadding="0"><tr><td align="center"><table role="presentation" width="620" style="max-width:620px;width:100%;background:#0d1320;border:1px solid #263247;border-radius:16px;overflow:hidden"><tr><td style="height:5px;background:linear-gradient(90deg,#55d6c2,#f2bd55,#ef7d76,#b86adf)"></td></tr><tr><td style="padding:26px"><div style="font-size:12px;letter-spacing:1.5px;color:#55d6c2;text-transform:uppercase">CodeNativeX Agent Notification</div><h1 style="margin:10px 0 8px;font-size:24px;color:#ffffff">Client outreach sent successfully</h1><p style="margin:0 0 22px;color:#aeb9cc;line-height:1.6">The approved outreach email was delivered by the agent.</p><table role="presentation" width="100%" cellspacing="0" cellpadding="8" style="background:#111a2a;border-radius:10px;color:#e9eef8;font-size:14px"><tr><td style="color:#8fa0b8;width:145px">Company</td><td><strong>${escapeHtml(companyName)}</strong></td></tr><tr><td style="color:#8fa0b8">Recipient</td><td>${escapeHtml(context.recipientEmail)}</td></tr><tr><td style="color:#8fa0b8">Subject</td><td>${escapeHtml(context.subject)}</td></tr><tr><td style="color:#8fa0b8">Audit report</td><td>${escapeHtml(auditLabel)}</td></tr><tr><td style="color:#8fa0b8">Gmail message ID</td><td>${escapeHtml(sendResult.gmailMessageId)}</td></tr><tr><td style="color:#8fa0b8">Gmail thread ID</td><td>${escapeHtml(sendResult.gmailThreadId)}</td></tr><tr><td style="color:#8fa0b8">Sent at</td><td>${escapeHtml(sentAt)}</td></tr></table><p style="margin:24px 0 0"><a href="${escapeHtml(`${dashboardBase}/dashboard/outreach`)}" style="display:inline-block;padding:12px 18px;border-radius:8px;background:#55d6c2;color:#07111a;text-decoration:none;font-weight:700">Open Outreach Dashboard</a></p><p style="margin:20px 0 0;color:#75849b;font-size:12px">Automated internal notification. The client received the short first-touch email without an attachment.</p></td></tr></table></td></tr></table></body></html>`;
return [{ json: { ...$json, shouldNotify, adminEmail, adminSubject, adminHtml, clientCompanyName: companyName, clientRecipientEmail: context.recipientEmail, reportFilename, clientGmailMessageId: sendResult.gmailMessageId, clientGmailThreadId: sendResult.gmailThreadId } }];

const prepared = $('Build Admin Send Notification').item.json;
const notificationAttempted = prepared.shouldNotify === true;
const notificationFailed = notificationAttempted && Boolean($json.error);
const notificationMessageId = notificationAttempted && !notificationFailed ? ($json.id ?? $json.messageId) : undefined;
return [{ json: { saved: prepared.saved === true, status: prepared.status, adminNotificationStatus: !notificationAttempted ? 'skipped_missing_admin_email_or_client_not_sent' : notificationFailed ? 'failed' : 'sent', adminNotificationMessageId: notificationMessageId, adminNotificationError: notificationFailed ? String($json.error.message ?? $json.error) : undefined } }];
